<?php require __DIR__.'/app/bootstrap.php'; require __DIR__.'/app/layout.php'; $user=require_permission('view_all_tickets');
$tickets=db()->query("SELECT t.*,d.name department,a.full_name assignee FROM tickets t JOIN departments d ON d.id=t.department_id LEFT JOIN users a ON a.id=t.assignee_id WHERE t.deleted_at IS NULL ORDER BY t.updated_at DESC")->fetchAll();
$status=['open'=>'Open','in_progress'=>'In Progress','pending'=>'Pending','closed'=>'Closed']; page_start('Issues register',$user); ?>
<div class="page-head"><div><p class="eyebrow">CNG / Jamesons</p><h1>Issues register</h1><p class="page-subtitle">Shared account concerns and escalations.</p></div><?php if(user_can('create_tickets')):?><a class="button" href="create-ticket.php">Create ticket</a><?php endif;?></div><div class="table-wrap"><table class="ticket-table"><thead><tr><?php foreach(['Status','Subject','Department','Category','Subcategory','Date Created','Date Updated','Date Closed','Assignee','Employee'] as $h):?><th><?=e($h)?></th><?php endforeach;?></tr></thead><tbody><?php foreach($tickets as $t):?><tr><td><span class="pill pill-<?=e(str_replace('_','-',$t['status']))?>"><?=e($status[$t['status']])?></span></td><td class="subject"><a href="ticket.php?id=<?=$t['id']?>"><?=e($t['subject'])?></a></td><td><?=e($t['department'])?></td><td><?=e($t['category'])?></td><td><?=e($t['subcategory'] ?? '—')?></td><td class="muted"><?=e($t['created_at'])?></td><td class="muted"><?=e($t['updated_at'])?></td><td class="muted"><?=e($t['closed_at'] ?? '—')?></td><td><?=e($t['assignee'] ?? 'Unassigned')?></td><td><?=e($t['employee_name'])?></td></tr><?php endforeach; if(!$tickets):?><tr><td colspan="10" class="muted">No tickets have been created yet.</td></tr><?php endif;?></tbody></table></div><?php page_end();
